-- ----------------------------
-- Table structure for zqzt_wf_copy
-- ----------------------------
DROP TABLE IF EXISTS `zqzt_wf_copy`;
CREATE TABLE `zqzt_wf_copy` (
  `copy_id` bigint NOT NULL AUTO_INCREMENT COMMENT '抄送主键',
  `title` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '抄送标题',
  `process_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '流程主键',
  `process_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '流程名称',
  `category_id` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '流程分类主键',
  `deployment_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '部署主键',
  `instance_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '流程实例主键',
  `task_id` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '任务主键',
  `user_id` bigint DEFAULT NULL COMMENT '用户主键',
  `originator_id` bigint DEFAULT NULL COMMENT '发起人主键',
  `originator_name` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '发起人名称',
  `create_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) COLLATE utf8mb4_general_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`copy_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程抄送表';

-- ----------------------------
-- Records of zqzt_wf_copy
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
