DROP TABLE IF EXISTS `zqzt_wf_deploy_form`;
CREATE TABLE `zqzt_wf_deploy_form` (
  `deploy_id` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '流程实例主键',
  `form_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '表单Key',
  `node_key` varchar(64) COLLATE utf8mb4_general_ci NOT NULL COMMENT '节点Key',
