  `node_name` varchar(255) COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '节点名称',
  `content` longtext COLLATE utf8mb4_general_ci COMMENT '表单内容',
  PRIMARY KEY (`deploy_id`,`form_key`,`node_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='流程实例关联表单';

